style.css:
css
/* Roblox Midnight — Roblox */
:root {
  /* swap these colors if you want */
  --my-bg: #111116;
  --my-panel: #1b1b24;
  --my-accent: #9b70ff;
  --my-text: #f2efff;
  --my-muted: #aaa5bd;
}

/* dark backgrounds */
html,
body {
  background: var(--my-bg) !important;
  color: var(--my-text) !important;
}

/* links */
a {
  color: var(--my-accent) !important;
}

/* buttons */
button,
input[type="button"],
input[type="submit"] {
  border-radius: 10px !important;
}

/* images */
img {
  border-radius: 8px !important;
}

/* cleaner typography */
body {
  font-family: Inter, "Segoe UI", sans-serif !important;
}

/* smoother selection */
::selection {
  background: var(--my-accent) !important;
  color: white !important;
}
